vrml.40:
#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Full

COMPONENT Sound : 2

Viewpoint {
  position 0 0 0
}

Sound {
  location 0 0 -5
  minBack 20
  minFront 20
  maxBack 40
  maxFront 40
  source DEF O AudioClip {
    url "media/tone22k-mono.wav"
  }
}

DEF L LoadSensor {
  children USE O
}

DEF PL Script {
  inputOnly SFBool  a
  inputOnly SFBool  l
  inputOnly SFFloat p

  url "ecmascript:
function a (v) { print ('L isActive ' + v); }
function l (v) { print ('L isLoaded ' + v); }
function p (v) { print ('L progress ' + v); }
"
}

DEF T TimeSensor {
  cycleInterval 0.5
  loop TRUE
}

DEF K Script {
  initializeOnly SFNode  o USE O
  inputOnly      SFTime  set_time
  initializeOnly SFInt32 n 49

  url "javascript:
function set_time (value) { ++ n;
   if (n === 20) { o.url = new MFString ('media/tone48k-stereo.wav'); o.url = new MFString ('media/tone22k-mono.wav'); }
}
"
  directOutput TRUE
}

DEF PO Script {
  inputOnly SFBool a
  inputOnly SFTime d

  url "javascript:
function a (v) { print ('O active ' + v); }
function d (v) { print ('O duration ' + v); }
"
}

ROUTE L.isActive TO PL.a
ROUTE L.isLoaded TO PL.l
ROUTE L.progress TO PL.p
ROUTE T.time TO K.set_time
ROUTE O.isActive TO PO.a
ROUTE O.duration_changed TO PO.d
